let shaderProgram;
const numFunctionsMax = 5;
const functionNames = ["sin", "cos", "tan", "sqrt", "abs"];
let functions = [];

const vertShader = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = vec4(aPosition, 1.0);
}
`;

const fragShader = `
precision highp float;

varying vec2 vTexCoord;

uniform vec2 u_resolution;
uniform int u_numFunctions;

uniform int u_functionTypes[5];
uniform float u_freqX[5];
uniform float u_freqY[5];
uniform float u_amp[5];
uniform float u_offset[5];

float applyFunction(int type, float x, float y) {
  if (type == 0) return sin(x + y);
  if (type == 1) return cos(x + y);
  if (type == 2) {
    float temp = tan(x + y);
    return abs(temp) > 100.0 ? 0.0 : temp;
  }
  if (type == 3) return sqrt(abs(x) + abs(y));
  if (type == 4) return abs(x + y);
  return 0.0;
}

void main() {
  float aspect = u_resolution.x / u_resolution.y;

  vec2 uv = vTexCoord * 2.0 - 1.0;
  uv.x *= aspect;

  float scaleFactor = 6.0;

  float mappedX = uv.x * scaleFactor * 3.141592653589793;
  float mappedY = uv.y * scaleFactor * 3.141592653589793;

  float patternValue = 0.0;

  for(int i = 0; i < 5; i++) {
    if(i >= u_numFunctions) break;

    float inputX = mappedX * u_freqX[i];
    float inputY = mappedY * u_freqY[i];
    float funcVal = applyFunction(u_functionTypes[i], inputX, inputY);
    float calcValue = funcVal * u_amp[i] + u_offset[i];

    patternValue += calcValue;
  }

  float r = clamp(255.0 - mod(patternValue * 50.0, 255.0), 0.0, 255.0);
  float g = clamp(255.0 - mod(patternValue * 100.0, 255.0), 0.0, 255.0);
  float b = clamp(255.0 - mod(patternValue * 150.0, 255.0), 0.0, 255.0);
  vec3 originalColor = vec3(r, g, b) / 255.0;

  gl_FragColor = vec4(originalColor, 1.0);
}
`;

let uiContainer;
let uiHeader;
let uiContent;

let numFunctionsSlider;
let functionTypeDropdowns = [];
let freqXSliders = [];
let freqYSliders = [];
let ampSliders = [];
let offsetSliders = [];

let aaCheckbox;
let aaLevelDropdown;

let isDragging = false;
let dragOffsetX = 0;
let dragOffsetY = 0;

let aaEnabled = false;
let aaLevel = 1;

let myCanvas;

const MAX_PIXEL_DENSITY = 4;

let randomizeButton;

// --- NEW VARIABLES FOR SMOOTHING ---
let targetNumFunctions;
let targetFunctionTypes = [];
let targetFreqX = [];
let targetFreqY = [];
let targetAmp = [];
let targetOffset = [];

let currentNumFunctions;
let currentFunctionTypes = [];
let currentFreqX = [];
let currentFreqY = [];
let currentAmp = [];
let currentOffset = [];


let animationProgress = 0;
const animationDuration = 25;
let isAnimating = false;

function setup() {
  pixelDensity(1);
  initFunctions();
  initCanvas();
  createUI();
  initTargets();

}

function initCanvas() {
    if (myCanvas) {
        myCanvas.remove();
    }
    if (aaEnabled) {
        aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
        pixelDensity(aaLevel);
    } else {
        aaLevel = 1;
        pixelDensity(1);
    }
    myCanvas = createCanvas(windowWidth, windowHeight, WEBGL);
    noStroke();
    shaderProgram = createShader(vertShader, fragShader);
    loop(); // Start the draw loop initially
}


function initTargets() {
    targetNumFunctions = numFunctionsMax;
    currentNumFunctions = numFunctionsMax;

  for (let i = 0; i < numFunctionsMax; i++) {
    targetFunctionTypes.push(functionNames.indexOf(functions[i].type));
    targetFreqX.push(functions[i].freqX);
    targetFreqY.push(functions[i].freqY);
    targetAmp.push(functions[i].amp);
    targetOffset.push(functions[i].offset);

    currentFunctionTypes.push(functionNames.indexOf(functions[i].type));
    currentFreqX.push(functions[i].freqX);
    currentFreqY.push(functions[i].freqY);
    currentAmp.push(functions[i].amp);
    currentOffset.push(functions[i].offset);
  }
}

function initFunctions() {
    functions = [];
    for (let i = 0; i < numFunctionsMax; i++) {
        const funcName = random(functionNames);
        functions.push({
            type: funcName,
            freqX: random(0.5, 5),
            freqY: random(0.5, 5),
            amp: random(0.5, 2),
            offset: random(-1, 1),
        });
    }
}


function draw() {
    if(isAnimating){
        animationProgress++;
        let t = animationProgress / animationDuration;
        t = constrain(t, 0, 1);
        t =  t < 0.5 ? 4 * t * t * t : 1 - pow(-2 * t + 2, 3) / 2;

         // Interpolate values
        currentNumFunctions = lerp(currentNumFunctions, targetNumFunctions, t);
        for(let i = 0; i < numFunctionsMax; i++){
            currentFunctionTypes[i] =  lerp(currentFunctionTypes[i], targetFunctionTypes[i], t);
            currentFreqX[i] = lerp(currentFreqX[i], targetFreqX[i], t);
            currentFreqY[i] = lerp(currentFreqY[i], targetFreqY[i], t);
            currentAmp[i] = lerp(currentAmp[i], targetAmp[i], t);
            currentOffset[i] = lerp(currentOffset[i], targetOffset[i], t);
        }

        if(animationProgress >= animationDuration){
            isAnimating = false;
            animationProgress = 0;
            noLoop();
        }
    }

    shader(shaderProgram);

    let numFunctions = int(currentNumFunctions);
    numFunctions = constrain(numFunctions, 1, numFunctionsMax);

    let functionTypes = [];
    let freqX = [];
    let freqY = [];
    let amp = [];
    let offset = [];

    for (let i = 0; i < numFunctionsMax; i++) {
        if (i < numFunctions) {
            functionTypes.push(int(currentFunctionTypes[i]));
            freqX.push(currentFreqX[i]);
            freqY.push(currentFreqY[i]);
            amp.push(currentAmp[i]);
            offset.push(currentOffset[i]);
        } else {
            functionTypes.push(0);
            freqX.push(1.0);
            freqY.push(1.0);
            amp.push(0.0);
            offset.push(0.0);
        }
    }

    shaderProgram.setUniform("u_resolution", [width, height]);
    shaderProgram.setUniform("u_numFunctions", numFunctions);
    shaderProgram.setUniform("u_functionTypes", functionTypes);
    shaderProgram.setUniform("u_freqX", freqX);
    shaderProgram.setUniform("u_freqY", freqY);
    shaderProgram.setUniform("u_amp", amp);
    shaderProgram.setUniform("u_offset", offset);


    beginShape(TRIANGLES);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, -1, 0, 1, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, 1, 0, 0, 1);
    endShape();
}


function windowResized() {
    initCanvas();
    updateShader();
}

function createUI() {
    uiContainer = createDiv();
    uiContainer.id('ui-container');
    uiContainer.style(`
    position: absolute;
    top: 20px;
    left: 20px;
    width: 350px;
    background: rgba(30, 30, 30, 0.9);
    color: #fff;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0,0,0,0.3);
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    user-select: none;
    z-index: 10;
  `);

    uiHeader = createDiv('Shader Controls');
    uiHeader.parent(uiContainer);
    uiHeader.style(`
    padding: 10px;
    cursor: move;
    background: rgba(50, 50, 50, 0.95);
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    font-weight: bold;
    text-align: center;
    font-size: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;

  `);

    randomizeButton = createButton('Randomize');
    randomizeButton.parent(uiHeader);
    randomizeButton.style(`
        position: absolute;
        right: 10px;
        padding: 5px 10px;
        background-color: #555;
        border: none;
        color: white;
        border-radius: 5px;
        cursor: pointer;
        font-size: 12px;

    `);
    randomizeButton.mousePressed(handleRandomize);

    uiContent = createDiv();
    uiContent.parent(uiContainer);
    uiContent.style(`
    padding: 10px;
    max-height: 80vh;
    overflow-y: auto;
  `);

    let numFuncLabel = createP('Number of Functions');
    numFuncLabel.parent(uiContent);
    numFuncLabel.style('margin', '10px 0 5px 0');
    numFunctionsSlider = createSlider(1, numFunctionsMax, numFunctionsMax, 1);
    numFunctionsSlider.parent(uiContent);
    numFunctionsSlider.style('width', '100%');
    numFunctionsSlider.input(updateTargetValues);

    createElement('hr').parent(uiContent).style('border: 0.5px solid #555; margin: 15px 0');

    for (let i = 0; i < numFunctionsMax; i++) {
        let funcContainer = createDiv();
        funcContainer.parent(uiContent);
        funcContainer.style(`
      padding: 10px;
      margin-bottom: 10px;
      background: rgba(50, 50, 50, 0.8);
      border-radius: 8px;
    `);

        let funcHeader = createDiv(`Function ${i + 1}`);
        funcHeader.parent(funcContainer);
        funcHeader.style(`
      margin-bottom: 8px;
      font-size: 14px;
      font-weight: bold;
      border-bottom: 1px solid #777;
      padding-bottom: 5px;
    `);

        let typeLabel = createSpan('Type: ');
        typeLabel.parent(funcContainer);
        typeLabel.style('font-size', '12px');
        let typeDropdown = createSelect();
        typeDropdown.parent(funcContainer);
        functionNames.forEach(name => typeDropdown.option(name));
        typeDropdown.selected(functions[i].type);
        typeDropdown.style('width', '100%');
        typeDropdown.changed(updateTargetValues);
        functionTypeDropdowns.push(typeDropdown);

        let freqXLabel = createSpan('Frequency X');
        freqXLabel.parent(funcContainer);
        freqXLabel.style('font-size', '12px; display: block; margin-top: 5px');
        let freqXSlider = createSlider(0.1, 10, functions[i].freqX, 0.1);
        freqXSlider.parent(funcContainer);
        freqXSlider.style('width', '100%');
        freqXSlider.input(updateTargetValues);
        freqXSliders.push(freqXSlider);

        let freqYLabel = createSpan('Frequency Y');
        freqYLabel.parent(funcContainer);
        freqYLabel.style('font-size', '12px; display: block; margin-top: 5px');
        let freqYSlider = createSlider(0.1, 10, functions[i].freqY, 0.1);
        freqYSlider.parent(funcContainer);
        freqYSlider.style('width', '100%');
        freqYSlider.input(updateTargetValues);
        freqYSliders.push(freqYSlider);

        let ampLabel = createSpan('Amplitude');
        ampLabel.parent(funcContainer);
        ampLabel.style('font-size', '12px; display: block; margin-top: 5px');
        let ampSlider = createSlider(0.1, 5, functions[i].amp, 0.1);
        ampSlider.parent(funcContainer);
        ampSlider.style('width', '100%');
        ampSlider.input(updateTargetValues);
        ampSliders.push(ampSlider);

        let offsetLabel = createSpan('Offset');
        offsetLabel.parent(funcContainer);
        offsetLabel.style('font-size', '12px; display: block; margin-top: 5px');
        let offsetSlider = createSlider(-5, 5, functions[i].offset, 0.1);
        offsetSlider.parent(funcContainer);
        offsetSlider.style('width', '100%');
        offsetSlider.input(updateTargetValues);
        offsetSliders.push(offsetSlider);
    }

    createElement('hr').parent(uiContent).style('border: 0.5px solid #555; margin: 15px 0');

    let aaEnableContainer = createDiv();
    aaEnableContainer.parent(uiContent);
    aaEnableContainer.style('margin-bottom', '10px');

    aaCheckbox = createCheckbox(' Enable Anti-Aliasing', false);
    aaCheckbox.parent(aaEnableContainer);
    aaCheckbox.style('font-size', '14px');
    aaCheckbox.changed(handleAAChange);

    let aaLevelLabel = createSpan(' AA Level');
    aaLevelLabel.parent(aaEnableContainer);
    aaLevelLabel.style('font-size', '12px; margin-left: 10px');

    aaLevelDropdown = createSelect();
    aaLevelDropdown.parent(aaEnableContainer);
    aaLevelDropdown.option('1x');
    aaLevelDropdown.option('2x');
    aaLevelDropdown.option('4x');
    aaLevelDropdown.selected('1x');
    aaLevelDropdown.style('width', '80px; margin-left: 10px');
    aaLevelDropdown.changed(handleAAChange);
    aaLevelDropdown.attribute('disabled', '');

    makeUIDraggable();

    uiContainer.elt.oncontextmenu = () => false;
}

function handleAAChange() {
    aaEnabled = aaCheckbox.checked();
    if (aaEnabled) {
        aaLevelDropdown.removeAttribute('disabled');
        let selectedAA = aaLevelDropdown.value();
        aaLevel = parseInt(selectedAA);
        aaLevel = constrain(aaLevel, 1, 4);
        initCanvas();
    } else {
        aaLevelDropdown.attribute('disabled', '');
        aaLevel = 1;
        initCanvas();
    }
    updateShader();
}

function handleRandomize() {
    initFunctions();
    for (let i = 0; i < numFunctionsMax; i++) {
        functionTypeDropdowns[i].selected(functions[i].type);
        freqXSliders[i].value(functions[i].freqX);
        freqYSliders[i].value(functions[i].freqY);
        ampSliders[i].value(functions[i].amp);
        offsetSliders[i].value(functions[i].offset);
    }
    updateTargetValues();
}


function makeUIDraggable() {
    uiHeader.mousePressed(startDrag);
    uiHeader.mouseReleased(endDrag);
}

function startDrag() {
    isDragging = true;
    let containerPos = uiContainer.position();
    dragOffsetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - containerPos.x;
    dragOffsetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - containerPos.y;
}

function endDrag() {
    isDragging = false;
}

function mouseDragged() {
    if (isDragging) {
        uiContainer.position((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - dragOffsetX, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - dragOffsetY);
    }
}

function updateTargetValues(){
    targetNumFunctions = int(numFunctionsSlider.value());
    targetNumFunctions = constrain(targetNumFunctions, 1, numFunctionsMax);

    for (let i = 0; i < numFunctionsMax; i++) {
       let typeName = functionTypeDropdowns[i].value();
       let typeIndex = functionNames.indexOf(typeName);
       targetFunctionTypes[i] = int(typeIndex);
       targetFreqX[i] = freqXSliders[i].value();
       targetFreqY[i] = freqYSliders[i].value();
       targetAmp[i] = ampSliders[i].value();
       targetOffset[i] = offsetSliders[i].value();
    }
    if(!isAnimating){
        isAnimating = true;
        loop();
    }
}

function updateShader() {
  loop();
  setTimeout(() => noLoop(), 10);
}

